    ('Shop', 'Wear, switch or remove a color', 'Colors you buy are yours. See what you own with .shop inventory, switch which one you are wearing with .shop equip, or take one off with .removemy <color name> (alias of .selfrole remove).', ('.shop inventory', '.shop equip', '.removemy <color name>')),
    ('Shop', 'Gift something from the shop', 'Buy something for a friend with .shop gift.', ('.shop gift',)),
    ('Shop', 'Word Reaction', "A Word Reaction costs 350,000 wondercoins. Run .shop buy, pick 'wondershop - additional purchases', choose Word Reaction. After buying, DM mod mail with the word you want.", ('.shop buy',)),
    ('Shop', 'Nickname Change', "A Nickname Change costs 400,000 wondercoins. Run .shop buy, pick 'wondershop - additional purchases', choose Nickname Change. After buying, DM mod mail with who you want changed and the new nickname. It changes someone else's nickname and lasts 24 hours.", ('.shop buy',)),
    ('Coins', 'Check your coins', 'See your wondercoin balance with .$ (or .bank balance). Claim free coins with .payday.', ('.$', '.bank balance', '.payday')),
