    ('Daily', 'Daily loop', 'Things to do every day: .payday for free coins, .card daily for a free card, answer the Daily Verdict in #qotd, care for the server pet in #cuddle, and say hi in #cuddle. Daily things reset at midnight Pacific time.', ('.payday', '.card daily', '.verdict', '.wonderpet')),
    ('Casino', 'Private gambling thread', 'Open a private thread to gamble in with .gamble, and close it with .endgambling. Games happen in #wondercasino.', ('.gamble', '.endgambling')),
    ('Casino', 'Shared blackjack table', 'Open a multiplayer blackjack lobby with .wonderjack table; others click Join.', ('.wonderjack table',)),
