    ('Casino', 'Duel a friend', 'Challenge another member to a best-of-3 for wondercoins; winner takes the wager. Check records with .duelstats.', ('.duel @user 5000', '.duelstats')),
    ('Casino', 'Lottery', 'Buy tickets when a lottery is open and check how many you hold.', ('.lottery buy', '.lottery inventory')),
    ('Fishing', 'Get started fishing', 'Type .fish to open the fishing game. You start with 100 FishPoints (FP). Equip a rod and bait before you cast. Check your stats and gear with .fishinfo. The full guide is pinned in #wondercasino.', ('.fish', '.fishinfo')),
    ('Fishing', 'Fishing rules', 'Pick your water: Pond (freshwater, beginner), Lake (bigger fish), River (mixed), Ocean (saltwater big game, the only place for all 5 legendary fish). Your rod must match the water type; sharks need the Shark Rod. Wait for a bite and do nothing; on FISH ON click Set Hook fast (about 5 seconds); then click Reel In steadily. If the screen says HIGH TENSION, stop clicking and wait a few seconds. Rarity: Common, Uncommon, Rare, Epic, Legendary. 1 FP = 20 wondercoins.', ('.fish',)),
    ('Chat drops', 'Games that pop up in #cuddle', 'Games appear in #cuddle on their own: quick math (solve first), hunt (type bang to shoot, salute if it is a safe animal), loot drop (click the button), react to win, pet the pupper, and boss fights where everyone attacks. Keep chatting and watch for them.', ()),
    ('Puzzle', 'Image puzzle', 'A picture is revealed piece by piece. Collect pieces and win the puzzle. See your progress with .puzzle status, the pieces you hold with .puzzle mypieces, and the all-time board with .puzzle leaderboard.', ('.puzzle status', '.puzzle mypieces', '.puzzle leaderboard')),
    ('Cards', 'Card collecting', 'Everyone gets a free card each day with .card daily. When a card drops in chat, type its code first to claim it. View your cards with .card, search with .card find <name>, show one full size with .card show <name>, look up any character with .card info <name>, pin favorites with .card showcase add <name>, give with .card give @user <name>, sell duplicates with .card sell token, and see top collectors with .card leaderboard.', ('.card daily', '.card', '.card find', '.card show', '.card give', '.card leaderboard')),
    ('Levels', 'Levels, profile and stars', 'Earn XP by chatting and being in voice. See your profile with .profile and rankings with .leveltop. Give stars with .stars @user and see the star leaderboard with .startop. Customize your profile with .setprofile. See your record across every game with .mystats. React with a star on a great message; six stars puts it on the starboard.', ('.profile', '.leveltop', '.stars', '.startop', '.setprofile', '.mystats')),
    ('Bumps', 'Bump the server', 'Bump the server on Disboard when the reminder pings. The Bumper role gets the reminder. See top bumpers with .bumpreward top week.', ('.bumpreward top week',)),
    ('Events', 'Events and birthdays', "See upcoming events with .event list; every event has Going, Maybe and Can't make it buttons, and you only get a reminder if you RSVP. Set your timezone with .event mytz. See who shows up most with .event regulars. Tell us your birthday with .birthday set March 14 (year optional) for a role, shout-out and coin gift, and see upcoming ones with .birthday upcoming. Every year you stay earns a year club role.", ('.event list', '.event mytz', '.event regulars', '.birthday set', '.birthday upcoming')),
    ('Pet', 'Server pet', 'One shared pet lives in #cuddle. Feed, play with and clean it once a day each (free); treats cost coins. If neglected for days it can run away. Past pets go in the Pet Hall. Commands: .wonderpet, .wonderpet me, .wonderpet carers, .wonderpet history.', ('.wonderpet', '.wonderpet me', '.wonderpet carers', '.wonderpet history')),
    ('Verdict', 'Daily Verdict', 'Every morning a question is posted in #qotd. Tap your own answer, then guess what most people will pick; the result is revealed with the next question. Good guessers climb the monthly Mind Reader list (play 5+ times to qualify). See it with .verdict top. Suggest a question with .verdict suggest Best snack? | Chips | Candy | Fruit (2 to 4 options; a mod approves it).', ('.verdict', '.verdict top', '.verdict suggest')),
    ('Voice', 'Voice rooms', 'Join the Room Creator channel and a room is made for you; you are the owner. Rename with .autoroom name My Room, set a limit with .autoroom users 4, make it public/locked/private with .autoroom public|locked|private, allow or deny people with .autoroom allow @user / .autoroom deny @user, and claim an abandoned room with .autoroom claim.', ('.autoroom name', '.autoroom users', '.autoroom locked', '.autoroom private', '.autoroom allow', '.autoroom claim')),
